#include <stdlib.h>
#include <string.h>
#include <openthread/instance.h>
#include <openthread/ip6.h>
#include <openthread/link.h>
#include <openthread/thread.h>
#include <openthread/thread_ftd.h>
#include <openthread/types.h>
#include <openthread/platform/radio.h>

static otInstance *sInstance;

extern "C" int LLVMFuzzerInitialize(int *argc, char ***argv)
{
    const otPanId panId = 0xdead;
    sInstance = otInstanceInitSingle();
    otLinkSetPanId(sInstance, panId);
    otIp6SetEnabled(sInstance, true);
    otThreadSetEnabled(sInstance, true);
    otThreadBecomeLeader(sInstance);
    (void)argc; (void)argv;
    return 0;
}

extern "C" int LLVMFuzzerTestOneInput(const uint8_t *data, size_t size)
{
    otRadioFrame frame;
    uint8_t *buf;
    if (size < 20 || size > OT_RADIO_FRAME_MAX_SIZE) return 0;
    buf = (uint8_t *)malloc(size);
    memset(&frame, 0, sizeof(frame));
    frame.mPsdu = buf;
    frame.mChannel = 11;
    frame.mLength = (uint8_t)size;
    memcpy(buf, data, frame.mLength);
    otPlatRadioReceiveDone(sInstance, &frame, OT_ERROR_NONE);
    free(buf);
    return 0;
}
