from pathlib import Path
p=Path('/workspace/poc2.cpp')
data=bytearray(20)
# 802.15.4 data frame with PAN IDs and IPv6/UDP/CoAP-ish payload not exact; just raw bytes for target parsing
# craft a short frame likely to reach MAC/6LoWPAN parsing and CoAP dispatch
payload = bytes([
    0x61,0x88, 0x00,0x00, 0xde,0xad, 0x12,0x34, 0x56,0x78, 0x9a,0xbc,
    0x00,0x00, 0x00,0x00, 0x00,0x00, 0x00,0x00
])
p.write_bytes(payload)
print('wrote', p, len(payload))
